,"future_buffer","ordering","sampling_allowed","aggregate"],"type":"object"},"type":"array"},"mode":{"enum":["ANALYSIS","RESEARCH"],"type":"string"},"question":{"description":"The user''s question, restated.","type":"string"},"relationships":{"description":"Catalog relationships between requests ([] for none), each with every key pair.","items":{"additionalProperties":false,"description":"data_need_spec/v2 (AI_ENABLE_COMPOSITE_KEYS, IP1 Stage B): a relationship names every entity key pair.","properties":{"as_of_direction":{"anyOf":[{"enum":["BACKWARD"],"type":"string"},{"type":"null"}],"description":"AS_OF only; else null."},"effective_from_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EFFECTIVE_DATED only: catalog column; else null."},"effective_to_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EFFECTIVE_DATED only: catalog column; else null."},"join_semantics":{"description":"One of the relationship''s supported_join_semantics in the catalog.","enum":["CURRENT_STATE","EXACT_DATE","AS_OF","EFFECTIVE_DATED"],"type":"string"},"join_type":{"description":"INNER restricts the left request to rows with a match in the right request''s scope; LEFT leaves it unrestricted. Each request is delivered as its own dataset; the analysis joins them.","enum":["INNER","LEFT"],"type":"string"},"left_columns":{"description":"Every entity key column of the catalog relationship on this side, in the order of its left_columns / right_columns without the time column (a composite key such as ticker, broker, investor_type and market_board names all of them).","items":{"type":"string"},"type":"array"},"left_request_id":{"type":"string"},"left_time_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EXACT_DATE / AS_OF: the catalog left time column; else null."},"relationship_id":{"description":"Catalog relationship_id between the two requests'' tables.","type":"integer"},"right_columns":{"description":"The matching right-side key column