     'Before presenting a Research Plan, check that its data exists, joins and fits: send the DataNeedSpec the plan will need (the same fields as submit_data_need_spec, without research_governance). The validator checks tables, columns, scopes, periods and catalog relationships, and the SQL Governor estimates each extraction without reading data. Returns FEASIBLE with draft_id and, per data request, the estimated rows and extraction parts; NOT_FEASIBLE naming the request whose data is too large or refused (narrow the period or universe, or report the limitation with alternatives); or REVISION_REQUIRED with issues (fix them, or report that the catalog offers no path, for example no documented relationship between two tables). Nothing is extracted and no revision is consumed. A Research Plan is presented only after a FEASIBLE check.')
) AS next(name, from_version, version, input_schema, purpose)
  ON previous.tool_name = next.name AND previous.version = next.from_version;

COMMENT ON COLUMN public."AI_column_catalog".cross_entity_aggregation IS
    'Rule for aggregating the column across entities of a finer grain (SUM, MIN, MAX); NULL means the column is not additive across entities and is never summed. Used by saniti.preaggregate before a relationship join and, since migration 20261002_002 (G18 phase 1), by a DataNeed request''s aggregate: the SQL Governor computes SUM across entities only for a SUM rule (re-derived from its own catalog contract). Read through the Governor catalog contract and shown by get_catalog_details.';

UPDATE public."Column_Catalog"
SET definition = 'Rule for aggregating the column across entities of a finer grain (SUM, MIN, MAX); NULL means the column is not additive across entities and is never summed. Used by saniti.preaggregate before a relationship join and, since migration 20261002_002 (G18 phase 1), by a DataNeed request''s aggregate: the SQL Governor computes SUM across entities only for a SUM rule (re-derived from its own catalog contract). Read through the Governor catalog contract and shown by get_catalog_details.',
    source_code_paths = ARRAY['database/migrations/20260927_005_cross_entity_aggregation_and_v2_contracts.sql',
                              'database/migrations/20261002_002_warehouse_summary_tool_catalog.sql',
                              'apps/market-sql-governor/app/catalog_contract.py',
                              'apps/market-sql-governor/app/extract.py',
                              'apps/market-python-sandbox/app/data_need.py',
                              'apps/market-python-sandbox/runtime/saniti_session.py']
WHERE table_schema = 'public' AND table_name = 'AI_column_catalog' AND column_name = 'cross_entity_aggregation';

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE NOT is_active AND ((tool_name = 'submit_data_need_spec' AND version = 'v5') OR (tool_name = 'check_data_feasibility' AND version = 'v4'))
        AND input_schema->'properties'->'data_requests'->'items'->'properties' ? 'aggregate'
        AND input_schema->'properties'->'data_requests'->'items'->'required' ? 'aggregate') <> 2 THEN
        RAISE EXCEPTION 'The warehouse summary tool contracts were not registered';
    END IF;
    IF (SELECT count(*) FROM public."Column_Catalog" WHERE table_name = 'AI_column_catalog'
        AND column_name = 'cross_entity_aggregation' AND definition LIKE '%G18 phase 1%') <> 1 THEN
        RAISE EXCEPTION 'The cross_entity_aggregation definition was not updated';
    END IF;
    IF (SELECT count(*) FROM public."AI_column_catalog" WHERE cross_entity_aggregation = 'SUM') <> 26 THEN
        RAISE EXCEPTION 'The cross-entity SUM rules changed unexpectedly';
    END IF;
END
$verify$;

COMMIT;
